if (typeof Counter !== 'function') {
  throw new Error('Counter should be exported as a function component');
}

// Mock React for testing
let currentState = 0;
const mockSetState = (newValue) => {
  currentState = typeof newValue === 'function' ? newValue(currentState) : newValue;
};

const React = {
  useState: (initialValue) => {
    currentState = initialValue;
    return [currentState, mockSetState];
  }
};

// Get the component structure
const result = Counter();

if (!result || typeof result !== 'object') {
  throw new Error('Counter should return a React element');
}

// Check for count display
const hasCountDisplay = JSON.stringify(result).includes('Count');
if (!hasCountDisplay) {
  throw new Error('Counter should display the count value');
}

// Check for buttons
const resultStr = JSON.stringify(result);
if (!resultStr.toLowerCase().includes('increment')) {
  throw new Error('Counter should have an Increment button');
}
if (!resultStr.toLowerCase().includes('reset')) {
  throw new Error('Counter should have a Reset button');
}

